'use strict';
// Equipment dice ("forge") and equipment stats, following forge-clone-2's rules.
// Data comes from js/equipment.js (generated by tools/build-equipment.ps1).

const Forge = (() => {
  const E = window.EQUIP;
  const slotOf = (part) => (part.startsWith('weapon') ? 'weapon' : part);

  const entries = E.catalog.map(([age, part, idx, bidx, shape, name, icon]) => ({ age, part, idx, bidx, shape, name, icon, slot: slotOf(part) }));
  const bySlotAge = {};
  const byKey = {};
  for (const e of entries) {
    (bySlotAge[e.slot + ':' + e.age] = bySlotAge[e.slot + ':' + e.age] || []).push(e);
    byKey[e.part + ':' + e.age + ':' + e.idx] = e;
  }

  const entry = (item) => byKey[item.part + ':' + item.age + ':' + item.idx];
  const tier = (item) => item.age + 1;
  const name = (item) => `[${AGE_SHORT[item.age]}] ${entry(item).name}`;
  const icon = (item) => 'assets/equip/' + entry(item).icon + '.png';

  // stat 0: damage, 1: health. Base x combat scale, grown by 1% per item level.
  function value(item, stat) {
    const e = entry(item);
    const base = e && E.stats[item.age + ':' + EQ_ITEM_TYPE[item.slot] + ':' + e.bidx];
    if (!base || !base[stat]) return 0;
    const baseline = base[stat] * STAT_SCALE;
    return Math.max(Math.floor(baseline * Math.pow(LEVEL_SCALING, item.lv - 1) + 0.5), Math.floor(baseline + 0.5) + item.lv - 1);
  }

  function optionValue(op) {
    const [lo, hi] = E.options[op[0]];
    return Math.floor((lo + (hi - lo) * op[1]) * 1000 + 0.5) / 1000;
  }
  function optionText(op) {
    const p = Math.round(optionValue(op) * 1000) / 10;
    return `+${p}% ${E.options[op[0]][2]}`;
  }

  // Comparable strength of one item (health weighs 1/8: forge-clone-2 health items carry 8x the base).
  function score(item) {
    if (!item) return 0;
    const raw = value(item, 0) + value(item, 1) / 8;
    let bonus = 0;
    for (const op of item.op) bonus += optionValue(op);
    return raw * (1 + bonus * 0.5);
  }
  const improves = (item, equipped) => score(item) > score(equipped);

  function rollAge(level) {
    const odds = E.odds[Math.max(0, Math.min(level, E.odds.length) - 1)];
    let r = Math.random(), sum = 0;
    for (let age = 0; age < 10; age++) { sum += odds[age]; if (r < sum) return age; }
    return 0;
  }

  // state: { diceLevel, brackets: { 'slot:age': n }, nextId }
  function roll(state) {
    const age = rollAge(state.diceLevel);
    const slot = EQ_SLOTS[Math.floor(Math.random() * EQ_SLOTS.length)];
    let a = age;
    while (a > 0 && !bySlotAge[slot + ':' + a]) a--;
    const pool = bySlotAge[slot + ':' + a];
    const e = pool[Math.floor(Math.random() * pool.length)];
    // Item level brackets advance each time this slot and age is forged.
    const key = slot + ':' + a;
    const bracket = state.brackets[key] || 0;
    const [lower, upper0] = E.brackets[Math.min(bracket, E.brackets.length - 1)];
    const upper = Math.min(upper0, ITEM_MAX_LEVEL);
    const lv = 1 + lower + Math.floor(Math.random() * (upper - lower + 1));
    let last = E.brackets.findIndex((b) => b[1] >= ITEM_MAX_LEVEL);
    if (last < 0) last = E.brackets.length - 1;
    state.brackets[key] = bracket < last ? bracket + 1 : bracket;

    const keys = Object.keys(E.options).filter((k) =>
      (e.part !== 'weapon_ranged' || k !== 'MELEE_DAMAGE') && (e.part !== 'weapon_melee' || k !== 'RANGED_DAMAGE'));
    const op = [];
    for (let i = 0; i < OPTION_COUNT[a]; i++) {
      const k = keys.splice(Math.floor(Math.random() * keys.length), 1)[0];
      op.push([k, Math.random()]);
      if (k === 'MELEE_DAMAGE' && keys.includes('RANGED_DAMAGE')) keys.splice(keys.indexOf('RANGED_DAMAGE'), 1);
      if (k === 'RANGED_DAMAGE' && keys.includes('MELEE_DAMAGE')) keys.splice(keys.indexOf('MELEE_DAMAGE'), 1);
    }
    return { id: state.nextId++, part: e.part, slot, age: a, idx: e.idx, lv, op };
  }

  // forge-clone-2 hands out a melee weapon and an armor on the first two forges.
  function starterItems(state) {
    return [
      { id: state.nextId++, part: 'weapon_melee', slot: 'weapon', age: 0, idx: 100, lv: 1, op: [] },
      { id: state.nextId++, part: 'armor', slot: 'armor', age: 0, idx: 101, lv: 1, op: [] },
    ];
  }

  function totals(equipped) {
    let attack = BASE_ATTACK, health = BASE_HEALTH;
    const opts = {};
    for (const k in E.options) opts[k] = 0;
    for (const slot of EQ_SLOTS) {
      const item = equipped[slot];
      if (!item) continue;
      attack += value(item, 0);
      health += value(item, 1);
      for (const op of item.op) opts[op[0]] += optionValue(op);
    }
    return { attack, health, opts };
  }

  // The uniform every soldier wears: equipped helmet and armor, the weapon in its role.
  function outfit(equipped) {
    const D = E.defaults;
    const o = { body: D.body, armL: D.armL, armR: D.armR, handL: null, handR: null, face: D.face, helmet: null,
      front: D.spear, frontScale: 1, back: D.bow, backScale: 1, shield: D.shield };
    const armor = equipped.armor && E.armors[tier(equipped.armor) + ':' + equipped.armor.idx];
    if (armor) [o.body, o.armL, o.armR, o.handL, o.handR] = armor;
    const helmet = equipped.helmet && E.helmets[tier(equipped.helmet) + ':' + equipped.helmet.idx];
    if (helmet) o.helmet = helmet;
    const w = equipped.weapon;
    if (w) {
      const bound = E.itemWeapons[tier(w) + ':' + w.idx];
      const shape = E.shapeWeapons[w.part + ':' + entry(w).shape];
      const label = bound ? bound[0] : shape && shape[0];
      const scale = bound ? bound[3] : 1;
      if (label) {
        if (w.part === 'weapon_ranged') { o.back = label; o.backScale = scale; } else { o.front = label; o.frontScale = scale; }
      }
    }
    for (const k of ['handL', 'handR', 'helmet']) if (o[k] === 'None') o[k] = null;
    return o;
  }

  function outfitLabels(o) {
    return [o.body, o.armL, o.armR, o.handL, o.handR, o.face, o.helmet, o.front, o.back, o.shield].filter(Boolean);
  }

  return { entry, tier, name, icon, value, optionValue, optionText, score, improves, roll, starterItems, totals, outfit, outfitLabels, slotOf };
})();
